private val WAVE_PATHS by lazy { WAVE_D.map { PathParser().parsePathString(it).toPath() } }
private val WAVE_TOP = Color(0xFFEFF4FE)

/** วาดคลื่นน้ำทับขอบล่างของ hero (สูง 165u เริ่มที่ -67u) แล้วลงสีแผงไล่จาก #EFF4FE ไปสีพื้น */
fun Modifier.waveEdge(bg: Color): Modifier = drawBehind {
    val u = size.width / 941f
    drawRect(Brush.verticalGradient(listOf(WAVE_TOP, bg)), topLeft = Offset(0f, 30f * u), size = androidx.compose.ui.geometry.Size(size.width, (size.height - 30f * u).coerceAtLeast(0f)))
    withTransform({ translate(0f, -67f * u); scale(u, u, Offset.Zero); translate(0f, -570f) }) {
        drawPath(WAVE_PATHS[0], Brush.verticalGradient(0f to Color(0x4DD8E8FC), .35f to Color(0xB8D8E8FC), .7f to Color(0xF2D8E8FC), 1f to Color(0xFFD8E8FC), startY = 570f, endY = 640f))
        drawPath(WAVE_PATHS[1], Brush.horizontalGradient(0f to Color(0xFF76B8FD), .28f to Color(0xFFA9D2FD), .5f to Color(0xFF62AEFD), 1f to Color(0xFF6FB3FD), startX = 0f, endX = 420f), alpha = .6f)
        drawPath(WAVE_PATHS[2], Color(0xFF6BB3FD), alpha = .6f)
        drawPath(WAVE_PATHS[3], WAVE_TOP)
    }
}
